import{_ as n,y as r,a as l,o as p,a2 as s,g as t,D as i,I as a}from"./chunks/framework.DCcmcJcL.js";const S=JSON.parse('{"title":"Sitemaps","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/sitemaps.md","filePath":"marketing/sitemaps.md","lastUpdated":1789441803000}'),d={name:"marketing/sitemaps.md"};function h(m,e,g,c,u,f){const o=r("ImagePopup");return p(),l("div",null,[e[3]||(e[3]=s('<h1 id="sitemaps" tabindex="-1">Sitemaps <a class="header-anchor" href="#sitemaps" aria-label="Permalink to &quot;Sitemaps&quot;">​</a></h1><p>A sitemap lists the pages of your storefront so search engines can find and index them. Bagisto builds sitemap files for your home page, categories, products and CMS pages, and serves them to search engines at one address for each channel.</p><p>Sitemaps are built only while <strong>Enabled</strong> is on in the <strong>Settings</strong> section of <strong>Configure &gt;&gt; General &gt;&gt; Sitemap</strong>. The <strong>File Limits</strong> section of that screen sets the <strong>Maximum no. of URLs per file</strong>. See <a href="./../configure/sitemap.html">Sitemap</a>. While <strong>Enabled</strong> is off, saving a sitemap still shows a success message, but no files are built.</p><h2 id="create-a-sitemap" tabindex="-1">Create a sitemap <a class="header-anchor" href="#create-a-sitemap" aria-label="Permalink to &quot;Create a sitemap&quot;">​</a></h2>',4)),t("ol",null,[e[1]||(e[1]=s("<li><p>Go to <strong>Marketing &gt;&gt; Search &amp; SEO &gt;&gt; Sitemaps</strong>.</p></li><li><p>Click <strong>Create Sitemap</strong>.</p></li><li><p>Enter the <strong>File Name</strong>. It must end in <code>.xml</code>, for example <code>sitemap.xml</code>, and contain only letters, numbers, hyphens, underscores and dots.</p></li><li><p>Enter the <strong>Path</strong>, a folder inside your store&#39;s sitemap storage. It must start and end with <code>/</code>, and can contain letters, numbers, <code>_</code>, <code>-</code>, <code>.</code> and <code>/</code>. Enter <code>/</code> to keep the files at the top of it.</p></li>",4)),t("li",null,[e[0]||(e[0]=t("p",null,[a("Under "),t("strong",null,"Channels"),a(", select the channels to build a sitemap for.")],-1)),i(o,{src:"/images/marketing/sitemap-create.png",alt:"The Create Sitemap dialog with sitemap.xml, the base path and the Default channel"})]),e[2]||(e[2]=t("li",null,[t("p",null,[a("Click "),t("strong",null,"Save Sitemap"),a(".")])],-1))]),e[4]||(e[4]=s('<p>Bagisto builds the files in the background after you save, which needs the queue worker your developer or host sets up. It adds numbers to the file name, so copy addresses from the list rather than typing them. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p><h2 id="submit-the-sitemap-to-search-engines" tabindex="-1">Submit the sitemap to search engines <a class="header-anchor" href="#submit-the-sitemap-to-search-engines" aria-label="Permalink to &quot;Submit the sitemap to search engines&quot;">​</a></h2><p>Submit <code>https://your-store-address/sitemap.xml</code> in Google Search Console, or in another search engine&#39;s tools. That address lists every sitemap file built for the channel you open it on. Your store&#39;s <code>robots.txt</code> already points search engines to it, and asks AI services not to use your content for training or as input.</p><p>The <strong>Sitemaps</strong> list shows each sitemap&#39;s <strong>ID</strong>, <strong>Channel</strong>, <strong>File Name</strong>, <strong>Path</strong> and <strong>Link for Google</strong>, with icons to edit and delete it. <strong>Link for Google</strong> shows the address of the file built for each channel.</p>',4)),i(o,{src:"/images/marketing/sitemaps.png",alt:"The Sitemaps list with a sitemap for the Default channel and its Link for Google address"}),e[5]||(e[5]=s('<p>When a channel has more links than one file can hold, Bagisto splits them into several files and lists them all.</p><h2 id="rebuild-the-sitemap" tabindex="-1">Rebuild the sitemap <a class="header-anchor" href="#rebuild-the-sitemap" aria-label="Permalink to &quot;Rebuild the sitemap&quot;">​</a></h2><p>Sitemap files aren&#39;t rebuilt on a schedule. After you add or remove products, categories or CMS pages, rebuild the sitemap:</p><ol><li>Go to <strong>Marketing &gt;&gt; Search &amp; SEO &gt;&gt; Sitemaps</strong>.</li><li>Click the edit icon of the sitemap.</li><li>Click <strong>Save Sitemap</strong>.</li></ol><p>Deleting a sitemap also deletes its files.</p>',5))])}const b=n(d,[["render",h]]);export{S as __pageData,b as default};
